const options = {
  method: 'POST',
  headers: {accept: 'application/json', 'content-type': 'application/json'},
  body: JSON.stringify({
    definition: {steps: [{name: 'string', count: 1}], mode: 'strict'},
    parts: [{object: 'part', sku: 'string'}]
  })
};

fetch('https://api.example.com/v1/widgets', options)
  .then(res => res.json())
  .then(res => console.log(res))
  .catch(err => console.error(err));

import requests

url = "https://api.example.com/v1/widgets"

payload = {
    "definition": {
        "steps": [
            {
                "name": "string",
                "count": 1
            }
        ],
        "mode": "strict"
    },
    "parts": [
        {
            "object": "part",
            "sku": "string"
        }
    ]
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)

